    private string _language = ApplicationLanguages.DetectSystem();

    public static AppLocalization Instance { get; } = new();

    public event PropertyChangedEventHandler? PropertyChanged;

    public string Language => _language;

    public string this[string key] => Translate(_language, key);

    public static string Text(string key) => Instance[key];

    public static string Format(string key, params object?[] args) =>
        string.Format(CultureInfo.CurrentCulture, Text(key), args);

    public static string Translate(string? language, string key)
    {
        var normalized = ApplicationLanguages.Normalize(language);
        var localized = normalized switch
        {
            ApplicationLanguages.Chinese => Chinese,
            ApplicationLanguages.Japanese => Japanese,
            _ => English
        };
        if (localized.TryGetValue(key, out var value))
        {
            return value;
        }

        return English.TryGetValue(key, out value) ? value : key;
    }

    internal static IReadOnlyCollection<string> TranslationKeys => English.Keys.ToArray();

    internal static bool HasExactTranslation(string? language, string key)
    {
        var localized = ApplicationLanguages.Normalize(language) switch
        {
            ApplicationLanguages.Chinese => Chinese,
            ApplicationLanguages.Japanese => Japanese,
            _ => English
        };
        return localized.ContainsKey(key);
    }

    public static void SetLanguage(string? language)
    {
        var normalized = ApplicationLanguages.Normalize(language);
        if (string.Equals(Instance._language, normalized, StringComparison.Ordinal))
        {
            return;
        }

        Instance._language = normalized;
        CultureInfo.CurrentCulture = ResolveCulture(normalized);
        CultureInfo.CurrentUICulture = ResolveCulture(normalized);
        Instance.PropertyChanged?.Invoke(Instance, new PropertyChangedEventArgs("Item[]"));
    }

    private static CultureInfo ResolveCulture(string language) => language switch
    {
        ApplicationLanguages.Chinese => CultureInfo.GetCultureInfo("zh-CN"),
        ApplicationLanguages.Japanese => CultureInfo.GetCultureInfo("ja-JP"),
        _ => CultureInfo.GetCultureInfo("en-US")
    };
}

[MarkupExtensionReturnType(typeof(string))]
public sealed class LocExtension : MarkupExtension
{
    public string Key { get; set; } = string.Empty;

    public override object ProvideValue(IServiceProvider serviceProvider) =>
        new Binding($"[{Key}]")
        {
            Source = AppLocalization.Instance,
            Mode = BindingMode.OneWay
        }.ProvideValue(serviceProvider);
}
